CREATE OR REPLACE VIEW `view_urlaubsvorschau_komplett_2` AS
with krankenquoten as (select `f`.`PersNr` AS `persnr`,`f`.`Schicht` AS `Schicht`,if(`d`.`brueckentag` = 1,7,weekday(`f`.`Datum`)) AS `wd`,sum(`ag`.`krank` = 1) / count(0) AS `krankenquote` from ((`tbl_ueb_fz_buchungen` `f` join `tbl_datum` `d` on(`f`.`Datum` = `d`.`datum` and `d`.`arbeitstag` = 1 and `d`.`datum` between curdate() - interval 6 month and curdate() - interval 1 day)) left join `tbl_abwesenheitsgrund` `ag` on(`f`.`Status` = `ag`.`kuerzel`)) group by `f`.`PersNr`,if(`d`.`brueckentag` = 1,7,weekday(`f`.`Datum`))), krankenquote_allgemein as (select `k`.`wd` AS `wd`,`k`.`Schicht` AS `schicht`,cast(avg(`k`.`krankenquote`) as decimal(2,2)) AS `krankenquote`,`p`.`oe` AS `oe`,`p`.`eg` = 'ZAK' AS `zak` from (`krankenquoten` `k` left join `tbl_ueb_personalakte_scd` `p` on(`p`.`persnr` = `k`.`persnr` and curdate() between `p`.`gueltig_von` and `p`.`gueltig_bis`)) where `p`.`beginn` < curdate() - interval 3 month and `k`.`Schicht` <> '' group by `k`.`wd`,`p`.`oe`,`p`.`eg` = 'ZAK'), main as (select `u`.`PersNr` AS `persnr`,`u`.`Datum` AS `datum`,`u`.`Schichtgruppe` AS `Schichtgruppe`,`u`.`Status` AS `Status`,`u`.`Kommen` AS `Kommen`,`u`.`Schicht` AS `Schicht`,`u`.`anwesenheit` AS `anwesenheit`,cast(case when `p`.`beginn` <= curdate() - interval 100 day then `sr`.`krankenquote` * 0.83 + `kqa`.`krankenquote` * 0.17 when `p`.`beginn` >= curdate() - interval 60 day then `kqa`.`krankenquote` else (to_days(curdate()) - to_days(`p`.`beginn`) - 60) / 60 * `sr`.`krankenquote` + (120 - (to_days(curdate()) - to_days(`p`.`beginn`))) / 60 * `kqa`.`krankenquote` end as decimal(2,2)) AS `Krankenquote` from ((((`tbl_ueb_fz_buchungen` `u` left join `tbl_ueb_personalakte_scd` `p` on(`u`.`PersNr` = `p`.`persnr` and `u`.`Datum` between `p`.`gueltig_von` and `p`.`gueltig_bis`)) left join `tbl_datum` `d` on(`u`.`Datum` = `d`.`datum`)) left join `krankenquoten` `sr` on(`u`.`PersNr` = `sr`.`persnr` and if(`d`.`brueckentag` = 1,7,weekday(`u`.`Datum`)) = `sr`.`wd`)) left join `krankenquote_allgemein` `kqa` on(`p`.`oe` = `kqa`.`oe` and if(`d`.`brueckentag` = 1,7,weekday(`u`.`Datum`)) = `kqa`.`wd` and `p`.`eg` = 'ZAK' = `kqa`.`zak`)))select `main`.`persnr` AS `PersNr`,`main`.`datum` AS `Datum`,`main`.`Schichtgruppe` AS `Schichtgruppe`,`main`.`Status` AS `Status`,case when `main`.`anwesenheit` = 'anw' then `main`.`Krankenquote` end AS `Krankenquote`,NULL AS `Krankenquote_Lfz`,`main`.`Kommen` AS `Kommen`,`main`.`Schicht` AS `Schicht`,`main`.`anwesenheit` AS `anwesenheit` from `main` where `main`.`datum` >= curdate();
